//! Synthesizes a minimal RSS 2.0 document from a `format = 'website'`
//! feed's already-scraped items, for its "View RSS feed" action - the
//! site itself never serves a real one, so this reconstructs what it
//! would look like from what `webpage.rs` already extracted. Marked as
//! auto-generated (a leading comment and a `<generator>` tag) so it's
//! never mistaken for something the site actually serves.

use chrono::DateTime;

pub struct SyntheticItem<'a> {
    pub guid: &'a str,
    pub title: Option<&'a str>,
    pub link: Option<&'a str>,
    pub summary: Option<&'a str>,
    pub published_at: i64,
}

const AUTO_GENERATED_NOTE: &str = "Auto-generated by Aequo: this site has no real RSS/Atom feed, \
so this is reconstructed from its scraped homepage listing.";

pub fn build(title: &str, link: &str, items: &[SyntheticItem<'_>]) -> String {
    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    out.push_str(&format!("<!-- {AUTO_GENERATED_NOTE} -->\n"));
    out.push_str("<rss version=\"2.0\"><channel>\n");
    out.push_str(&format!("  <title>{}</title>\n", escape(title)));
    out.push_str(&format!("  <link>{}</link>\n", escape(link)));
    out.push_str("  <generator>Aequo (auto-generated - no real feed was found)</generator>\n");
    for item in items {
        out.push_str("  <item>\n");
        if let Some(value) = item.title {
            out.push_str(&format!("    <title>{}</title>\n", escape(value)));
        }
        if let Some(value) = item.link {
            out.push_str(&format!("    <link>{}</link>\n", escape(value)));
        }
        out.push_str(&format!(
            "    <guid isPermaLink=\"false\">{}</guid>\n",
            escape(item.guid)
        ));
        if let Some(value) = item.summary {
            out.push_str(&format!(
                "    <description>{}</description>\n",
                escape(value)
            ));
        }
        if let Some(date) = DateTime::from_timestamp(item.published_at, 0) {
            out.push_str(&format!("    <pubDate>{}</pubDate>\n", date.to_rfc2822()));
        }
        out.push_str("  </item>\n");
    }
    out.push_str("</channel></rss>\n");
    out
}

fn escape(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&apos;"),
            other => out.push(other),
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn marks_itself_auto_generated_escapes_values_and_stays_parseable() {
        let items = [SyntheticItem {
            guid: "abc123",
            title: Some("A & B <tag>"),
            link: Some("https://example.com/a&b"),
            summary: Some("Has <b>html</b> & stuff"),
            published_at: 1_700_000_000,
        }];
        let xml = build("Blog & Co", "https://example.com/", &items);

        assert!(xml.starts_with("<?xml version=\"1.0\" encoding=\"UTF-8\"?>"));
        assert!(xml.contains("Auto-generated by Aequo"));
        assert!(xml.contains("<generator>Aequo"));
        assert!(xml.contains("<title>Blog &amp; Co</title>"));
        assert!(xml.contains("<title>A &amp; B &lt;tag&gt;</title>"));
        assert!(xml.contains("<link>https://example.com/a&amp;b</link>"));
        assert!(xml.contains("<description>Has &lt;b&gt;html&lt;/b&gt; &amp; stuff</description>"));
        assert!(xml.contains("<guid isPermaLink=\"false\">abc123</guid>"));

        // A generated feed must itself be valid RSS, not just look like it.
        let parsed = crate::fetch::parser::parse(xml.as_bytes()).unwrap();
        assert_eq!(parsed.entries.len(), 1);
    }

    #[test]
    fn items_missing_optional_fields_are_still_valid() {
        let items = [SyntheticItem {
            guid: "only-a-guid",
            title: None,
            link: None,
            summary: None,
            published_at: 0,
        }];
        let xml = build("Title", "https://example.com/", &items);
        let parsed = crate::fetch::parser::parse(xml.as_bytes()).unwrap();
        assert_eq!(parsed.entries.len(), 1);
    }
}
